pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;
    address public constant OPTIMISTIC_ASSERTER = address(0x1);

    function setUp() public {
        c = new BaseEscalationManager(address(this));
    }

    function _test(bytes32 assertionId, bool assertedTruthfully) internal {
        bool success = true;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }

    function testFuzz_test(bytes32 assertionId, bool assertedTruthfully) public {
        _test(assertionId, assertedTruthfully);
    }

    receive() external payable {}
}
